```

2. Definir las funciones:

```cpp
// función para contar el número de apariciones de una palabra en una línea
unsigned int contarPalabraEnLinea(const std::string& linea, const std::string& palabra) {
    unsigned int contador = 0;
    size_t posicion = 0;

    while ((posicion = linea.find(palabra, posicion)) != std::string::npos) {
        ++contador;
        posicion += palabra.length();
    }

    return contador;
}

// función principal para contar el número de apariciones de una palabra en un archivo
unsigned int contarPalabraEnArchivo(const std::string& archivo, const std::string& palabra) {
    unsigned int contador = 0;
    std::ifstream archivo_leido(archivo);
    std::string linea;

    if (archivo_leido.is_open()) {
        while (std::getline(archivo_leido, linea)) {
            contador += contarPalabraEnLinea(linea, palabra);
        }
        archivo_leido.close();
    } else {
        std::cerr << "Error al abrir el archivo: " << archivo << std::endl;
    }

    return contador;
}

// función para ejecutar el programa y mostrar el resultado
void ejecutar(const std::string& archivo, const std::string& palabra) {
